    uint32_t prev = g_fine_acc;
    g_fine_acc++;
    uint32_t delta = g_fine_acc - prev;
    // Se delta > 1, um tick foi perdido; ignorar ou tratar erro
    if (delta > 1) delta = 1; // forçar avanço de 1 µs

