extern SVPWMHalfBridge* g_svpwm;

// ============================ CONSTRUTOR ============================
SVPWMHalfBridge::SVPWMHalfBridge(uint8_t pa, uint8_t pb, uint8_t pc)
    : Vdc(0.), fsw_hz(0), resolution(10), deadtime_cycles(0),
      target_phase_peak(0.), pinA(pa), pinB(pb), pinC(pc),
      omega_rad_per_sec(0.), phase_offset_global(0.), running(false),
      t_start_us(0), t_curr_us(0), Ts_us(0),
      num_global_events(0)
