    // Limpa listas de eventos por fase
    for (int i = 0; i < 3; i++) {
        events_per_phase[i] = {{0, {0,0,0}}, {UINT32_MAX, {0,0,0}}};
        num_events_phase[i] = 1; // primeiro evento já apontado
    }
}

// ============================ INIT ===================================
void SVPWMHalfBridge::init() {
    if (fsw_hz <= 0) return;
    Ts_us = (1000000 + fsw_hz - 1) / fsw_hz; // período em µs (valor inteiro)

    // Configura 3 canais LEDC usando timer 0 (intercalado)
    ledcSetup(0, fsw_hz, resolution);
    ledcSetup(1, fsw_hz, resolution);
    ledcSetup(2, fsw_hz, resolution);
    ledcAttachPin(pinA, 0);
    ledcAttachPin(pinB, 1);
    ledcAttachPin(pinC, 2);

    // Estados iniciais: ambas as chaves desligadas
    phase_states[0] = 0;
    phase_states[1] = 0;
    phase_states[2] = 0;
    // Zera acumulador do timer fino
    g_fine_acc = 0;
}

void SVPWMHalfBridge::setParams(float Vdc_, uint32_t fsw_, int32_t res_,
                                int32_t td_, float Vph_, float omega_, float offset_) {
    Vdc = Vdc_;
    fsw_hz = fsw_;
    resolution = res_;
    deadtime_cycles = td_;
    target_phase_peak = Vph_;
    omega_rad_per_sec = omega_;
    phase_offset_global = offset_;

    if (Vdc > 0) {
        Ts_us = (1000000 + fsw_ - 1) / fsw_;
        // Limita a tensão-alvo para não exceder a capacidade da meia ponte
        float max_vp = Vdc / 2.0f;
        if (target_phase_peak > max_vp) {
            target_phase_peak = max_vp;
        }
        // O deadtime será compensado ao longo do tempo; aqui só guardamos o parâmetro.
    }
}

void SVPWMHalfBridge::setDeadtime(int32_t cycles) {
    if (cycles >= 0) {
        deadtime_cycles = cycles;
    }
}

// ============================ START/STOP =============================
void SVPWMHalfBridge::start() {
    if (!running) {
        running = true;
        t_start_us = g_fine_acc; // marca o início do primeiro período
        computeNextPeriod();     // calcula os eventos do primeiro período
        // O loop principal de execução fica no step() acionado pelo ISR
    }
}

void SVPWMHalfBridge::stop() {
    running = false;
}

// ====================== ISR DO TIMER FINO (1 µs) =====================
/// Esta função deve ser chamada de um ISR configurado no ESP32
/// para interromper a cada 1 µs (ex.: Timer3 com prescaler adequado).
