// ============================ STEP () ================================
/// Avança o relógio virtual em 1 µs e processa eventos pendentes.
void SVPWMHalfBridge::step() {
    if (!running) return;

    // Advancing virtual time
    uint32_t delta = 1; // ISR garante 1 tick por chamada
    t_curr_us += delta;

    // Detectar fim de período
    if (t_curr_us >= Ts_us) {
        t_curr_us -= Ts_us;
        // Novo período começou: gerar eventos
        computeNextPeriod();
        // Marca que há novos eventos pendentes (próximos passos vão consumi-los)
        g_need_new_events = true; // membro adicionado abaixo
        return;
    }

    // Aplicar eventos que agora estão devidos
    int last_processed = 0; // será atualizado
    for (int i = 0; i < 3; i++) {
        // Verifica se o próximo evento da fase i já ocorreu
        if (g_need_apply_event(i)) {
            applyEvent(i);
        }
    }

    // Escreve contagens no LEDC
    writeLeds();
}

