/// Gera os eventos de SVPWM para o próximo período.
/// Deve ser chamada quando t_curr_us retorna a 0 após completar um período.
void SVPWMHalfBridge::computeNextPeriod() {
    // 1. Calcular ângulo de referência no início do período (t=0)
    float theta = phase_offset_global; // em radianos

    // 2. Discretizar o período em passos de 1 µs
    //    Como Ts_us = 50 µs para 20 kHz, o loop roda 50 vezes.
    //    Dentro dele, determinamos setores e resolvemos alocações.

    float dtheta_us = omega_rad_per_sec * 1e-6f; // variação angular por µs
    float sec_wid = PI / 3.0f; // largura de um setor

    int t_step = 0;
    float th = theta;
    int sector = getSector(th);
    int prev_sector = -1;

    // Armazena temporariamente alocações para o setor atual
    float p1 = 0., p2 = 0., pz = 0.; // frações do período

    // Loop micro a micro
    while (t_step < Ts_us) {
        // Muda de setor?
        if (sector != prev_sector || prev_sector == -1) {
            // Resolve alocação para este setor
            solveSectorAllocation(th, 0.0f, 1.0f, M); // X=th_proj, Y=0 placeholder (ver abaixo)
            // Na verdade, precisamos projetar th no sistema local
            // Vamos calcular X e Y corretamente:
            float a = vec_ang[sector]; // ângulo do vetor inferior do setor
            float X = Vref_alpha * cos(a) + Vref_beta * sin(a);
            float Y = -Vref_alpha * sin(a) + Vref_beta * cos(a);
            solveSectorAllocation(X, Y, M);

            // Vectores do setor
            int low = sector;
            int high = (sector + 1) % 6;
            // Vetor no meio (zero vector aproximado; usaremos Z+ sempre)
            float vz_a = (vec_ang[low] + vec_ang[high]) / 2.0f;

            // Tempos em µs
            uint32_t t1 = (uint32_t)(p1 * Ts_us);
            uint32_t tz = (uint32_t)(pz * Ts_us);
            uint32_t t2 = Ts_us - t1 - tz; // pode ser 0

            // Evento 1: início do setor com vetor 'low'
            if (t1 > 0 || (t1 == 0 && t2 > 0)) { // se t1=0, vai direto pro próximo
                addEventToPhase(0, 0, low, getVecState(low)); // tempo 0
            }
            // Evento 2: zero vector (se pz > 0)
            if (tz > 0) {
                addEventToPhase(0, t1, MID_ZERO_IDX, ZPLUS_STATE); // índice fictício
            }
            // Evento 3: vetor 'high'
            if (t2 > 0) {
                addEventToPhase(0, t1 + tz, high, getVecState(high));
            }
            // Ordena eventos da fase 0
            sortEventsByTime(0);
        }

        // Atualiza ângulo e setor
        th += dtheta_us;
        sector = getSector(th);
        prev_sector = sector;

        t_step++;
    }

    // Após o loop, salvamos todos os eventos por fase
    // (A função addEventToPhase preenche events_per_phase[i])
}

