int getSector(float th) {
    int s = (int)(th / sec_wid) % 6;
    if (s < 0) s += 6;
    return s;
}

void solveSectorAllocation(float X, float Y, float M) {
    // M é a normalização do vetor de referência (0 a ~0.866 para sinusoidal)
    // Aqui estamos trabalhando com X,Y já escalados para M=1? Precisamos ajustar.
    // Na prática, calculamos M alvo e usamos como referência.
    // Para simplificar, assumimos que X,Y já estão em unidades de Vm (raio do hexágono).
    // Vamos resolver p1,p2,pz sem depender de M diretamente, mas usando X,Y como projeções.
    // A equação correta considera que queremos atingir M*Vr onde Vr é o raio do hexágono.
    // Mas para manter simples, vamos usar o método de projeção direta.
    // Deixe-me definir constants:
    float sq3 = SQRT3;
    float inv_sq3 = INV_Q3;
    float qhalf = HALF;
    // Coeficientes derivados
    float c1 = 0.5f; // cos60
    float c2 = sq3 * 0.5f; // sin60
    float c3 = sq3 * 0.5f; // cos30 (para zero vector)
    float c4 = 0.5f; // sin30

    // Equações:
    // X = p1 + 0.5 p2 + 0.5*sqrt3 * pz   (porque c3=cos30=0.866, mas aqui normalizamos? Vamos reescalonar)
    // Na verdade, as componentes dos vetores em unidades de Vm são:
    // V1 = (1, 0)
    // V2 = (0.5, sqrt3/2)
    // Vz = (sqrt3/2, 0.5)  (direção do zero vector Z+)
    // Então:
    // X = p1*1 + p2*0.5 + pz*(sqrt3/2)
    // Y = p1*0 + p2*(sqrt3/2) + pz*0.5
    // p1 + p2 + pz = 1

    // Solução:
    // Da eq Y: p2 = (Y - 0.5*pz) * (2/sqrt3)
    float p2_coef_Y = (2.0f / sq3); // fator para Y
    float one_over_two_sq3 = 1.0f / (2.0f * sq3);

    float p2_expr = p2_coef_Y * (Y - 0.5f * pz);

    // Substituindo na eq X:
    // X = (1 - p2 - pz) + 0.5*p2 + (sqrt3/2)*pz
    // => X = 1 - 0.5*p2 - pz + (sqrt3/2)*pz
    // => 1 - X = 0.5*p2 + pz*(1 - sqrt3/2)
    float rhs_const = 1.0f - X;
    float coeff_pz = (1.0f - sqrt3 * 0.5f); // = (2-sqrt3)/2 ≈ 0.13397

    // Agora: rhs_const = 0.5*p2 + coeff_pz*pz
    // E p2 = p2_coef_Y*(Y - 0.5*pz)
    // Substituindo:
    // rhs_const = 0.5 * p2_coef_Y * (Y - 0.5*pz) + coeff_pz * pz
    // => rhs_const - (0.5 * p2_coef_Y * Y) = pz * (coeff_pz + 0.5 * p2_coef_Y * 0.5)
    // Nota: 0.5 * p2_coef_Y * 0.5 = 0.5^2 / sqrt3 = 0.25/sqrt3
    // Vamos calcular numericamente para evitar erros:
    float term_y = 0.5f * p2_coef_Y * Y; // = Y / (sqrt3)
    float coeff_pz_total = coeff_pz + 0.5f * one_over_two_sq3; // = 0.13397 + 0.14434 = 0.27831
    // Espera, vamos refazer: 0.5 * p2_coef_Y * 0.5 = 0.25 / sqrt3 = 0.14434
    // Então coeff_pz_total = coeff_pz + 0.14434 = 0.13397 + 0.14434 = 0.27831
    // Mas antes eu tinha outro valor; vou seguir essa derivação correta agora.

    // Reorganizando:
    // rhs_const - term_y = pz * (coeff_pz + 0.25/sqrt3)
    // Let A = rhs_const - term_y
    // Let B = coeff_pz + 0.25f/sqrt3
    // pz = A / B

    float A_val = rhs_const - term_y;
    float B_val = coeff_pz + (0.25f / sq3); // = 0.27831
    pz = A_val / B_val;

    // Garante pz entre 0 e 1 (pode requerer clamp leve)
    if (pz < 0) pz = 0;
    if (pz > 1) pz = 1;

    p2 = (p2_coef_Y * (Y - 0.5f * pz));
    p1 = 1.0f - p2 - pz;
    if (p1 < 0) p1 = 0; // fallback (raro)
    if (p2 < 0) p2 = 0;
    if (p1 > 1 - p2 - pz) p1 = 1.0f - p2 - pz;

    // Ajuste fino para garantir soma = 1
    float sum_check = p1 + p2 + pz;
    float delta_p = (1.0f - sum_check); // pequena correção distribuída igualmente
    p1 += delta_p / 3.0f;
    p2 += delta_p / 3.0f;
    pz += delta_p / 3.0f;
    // Reaplicar clamps se necessário (geralmente ok)
}

