    timer3_config_t cfg = {0};
    cfg.resolver = 0;            // 8 bits? Não, 32 bits permite prescaler grande
    cfg.prescaler = 8192;        // 8MHz / 8192 = 976 Hz -> tick = 1.024 ms. Não serve.
